package local.yxp;

import static local.yxp.BattleTestDecks.allowRepeatedSingleUseCards;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static local.yxp.Models.*;
import static local.yxp.Engine.*;
class ResurrectionSealTest {
 final Rules rules=new Rules();final Engine engine=new Engine(rules);
 Player p(String id,int card,List<Integer> talents,Map<String,Integer> buffs){return new Player(id,id,0,400,800,10,0,0,Collections.nCopies(8,card),talents,buffs);}
 Fighter[] pair(Map<String,Integer> buffs){var a=new Fighter(p("A",1000005,List.of(),buffs));var b=new Fighter(p("B",1000005,List.of(),Map.of()));var res=new Resolution();res.log=new ArrayList<>();res.fighters=new Fighter[]{a,b};for(var f:res.fighters){f.rules=rules;f.resolution=res;}a.opponent=b;b.opponent=a;return res.fighters;}
 Result run(String stage,Player a){return engine.simulate(new Request(Rules.ID,"STANDARD",stage,"A",List.of(allowRepeatedSingleUseCards(a),p("B",1000005,List.of(),Map.of()))));}
 State end(Result r,int turn){return r.events().stream().filter(e->e.turn()==turn&&e.type().equals("TURN_END")).findFirst().orElseThrow().states().getFirst();}
 @Test void flameOpeningGrantsOneCharge(){var r=run("PRE_OPENING",p("A",1000005,List.of(139),Map.of()));assertEquals(1,r.events().stream().filter(e->e.type().equals("TALENT")).findFirst().orElseThrow().states().getFirst().statuses().get("flameRevive"));}
 @Test void sealOpeningGrantsOneCharge(){assertEquals(1,end(run("PRE_OPENING",p("A",1000005,List.of(140),Map.of())),1).statuses().get("burningSeal"));}
 @Test void openingTalentsCannotBeReappliedToSnapshot(){for(int t:List.of(139,140))assertThrows(Rejected.class,()->run("POST_OPENING",p("A",1000005,List.of(t),Map.of())));}
 @Test void flameResetsBothLifeAndCapAndConsumesEntireBuff(){var f=pair(Map.of("flameRevive",2))[0];f.hp=-90;assertFalse(isDead(f));assertEquals(15,f.hp);assertEquals(15,f.maxHp);assertEquals(0,f.status("flameRevive"));f.hp=0;assertTrue(isDead(f));}
 @Test void flameWorksAtZeroCap(){var f=pair(Map.of("flameRevive",1))[0];f.hp=-1;f.maxHp=0;assertFalse(isDead(f));assertEquals(15,f.hp);assertEquals(15,f.maxHp);}
 @Test void flameDoesNotRunHealingCallbacksOrLossHistory(){var fs=pair(Map.of("flameRevive",1,"noHealing",9,"healToSharpRounds",9,"overflowGrowth",9,"reverseRounds",9));var f=fs[0];f.hp=-1;assertFalse(isDead(f));assertEquals(15,f.hp);for(String k:List.of("healingTotal","turnHealing","sharpness","maxHpLost","hpLost"))assertEquals(0,f.status(k),k);assertEquals(400,fs[1].hp);}
 @Test void flameHasPriorityOverWheelAndWheelRemainsForLaterDeath(){var f=pair(Map.of("flameRevive",1,"reviveWheel",1))[0];f.hp=-1;assertFalse(isDead(f));assertEquals(1,f.status("reviveWheel"));f.hp=-3;assertFalse(isDead(f));assertEquals(15,f.hp);assertEquals(0,f.status("reviveWheel"));assertEquals(2,f.resolution.log.stream().filter(e->e.type().equals("RESURRECTION")).count());}
 @Test void livingFighterDoesNotSpendAnyRevival(){var f=pair(Map.of("flameRevive",1,"reviveWheel",1))[0];assertFalse(isDead(f));assertEquals(1,f.status("flameRevive"));assertEquals(1,f.status("reviveWheel"));assertTrue(f.resolution.log.isEmpty());}
 @Test void banPreventsBothRevivalPathsWithoutSpendingCharges(){var f=pair(Map.of("flameRevive",1,"reviveWheel",1,"reviveBlocked",1))[0];f.hp=-1;assertTrue(isDead(f));assertEquals(1,f.status("flameRevive"));assertEquals(1,f.status("reviveWheel"));assertTrue(f.resolution.log.isEmpty());}
 @Test void banAlsoPreventsHealingAnAlreadyDeadFighterWithReviveFlag(){var f=pair(Map.of("reviveBlocked",1))[0];f.hp=-1;heal(new ArrayList<>(),f,50,true);assertEquals(-1,f.hp);f.hp=10;heal(new ArrayList<>(),f,5,true);assertEquals(15,f.hp);}
 @Test void wheelAtZeroCapRestoresOneCapBeforeHealing(){var f=pair(Map.of("reviveWheel",1))[0];f.hp=-5;f.maxHp=0;assertFalse(isDead(f));assertEquals(1,f.maxHp);assertEquals(1,f.hp);assertEquals(0,f.status("reviveWheel"));}
 @Test void blockedWheelStillSpendsItsCharge(){var f=pair(Map.of("reviveWheel",1,"noHealing",1))[0];f.hp=-5;assertTrue(isDead(f));assertEquals(-5,f.hp);assertEquals(0,f.status("reviveWheel"));}
 @Test void deathBattleWaitsUntilRevivalAttemptsFinish(){var f=pair(Map.of("flameRevive",1,"deathBattleWill",1))[0];f.hp=-1;assertFalse(isDead(f));assertEquals(1,f.status("deathBattleWill"));assertEquals(0,f.status("deathBattleActive"));}
 @Test void deathBattleStillWorksUnderRevivalBan(){var f=pair(Map.of("flameRevive",1,"deathBattleWill",1,"reviveBlocked",1))[0];f.hp=-1;assertFalse(isDead(f));assertEquals(0,f.status("deathBattleWill"));assertEquals(1,f.status("deathBattleActive"));assertEquals(1,f.status("flameRevive"));}
 @Test void bothDeadFightersAreCheckedWithoutShortCircuiting(){var fs=pair(Map.of());fs[0].hp=-10;fs[1].hp=-1;fs[1].statuses.put("flameRevive",1);assertTrue(deaths(fs[0],fs[1]));assertEquals(15,fs[1].hp);}
 @Test void internalInjuryDeathRevivesAndContinuesOwnAction(){var a=new Player("A","A",0,1,100,0,0,0,Collections.nCopies(8,1000005),List.of(),Map.of("internalInjury",2,"flameRevive",1));var r=run("POST_OPENING",a);assertTrue(r.events().stream().anyMatch(e->e.turn()==1&&e.type().equals("RESURRECTION")));assertTrue(r.events().stream().anyMatch(e->e.turn()==1&&e.type().equals("CARD_PLAY")));assertEquals(15,end(r,1).hp());}
 @Test void sealConsumesPhysicalSlotAndChasesInsteadOfRepeatingCard(){var r=run("PRE_OPENING",p("A",7000001,List.of(140),Map.of()));var s=end(r,1);assertEquals(List.of(0),s.consumedSlots());assertEquals(0,s.statuses().get("burningSeal"));assertEquals(2,r.events().stream().filter(e->e.turn()==1&&e.type().equals("CARD_PLAY")).count());assertFalse(r.events().stream().anyMatch(e->e.turn()==1&&e.type().equals("CARD_REPEAT")));assertEquals(1,s.statuses().get("chaseCount"));}
 @Test void sealWorksWithSnapshotChargeWithoutReplayingOpening(){var r=run("POST_OPENING",p("A",7000001,List.of(),Map.of("burningSeal",1)));assertEquals(List.of(0),end(r,1).consumedSlots());assertFalse(r.events().stream().anyMatch(e->e.type().equals("TALENT")));}
 @Test void sealDoesNotTriggerOnNonSeal(){var r=run("PRE_OPENING",p("A",1000005,List.of(140),Map.of()));assertEquals(1,end(r,1).statuses().get("burningSeal"));assertTrue(end(r,1).consumedSlots().isEmpty());}
 @Test void virtualSealsDoNotSpendChargeOrConsumeSourceSlot(){var f=pair(Map.of("burningSeal",1))[0];TalentEffects.seal(new ArrayList<>(),f,rules.byId.get(7000001),true);assertEquals(1,f.status("burningSeal"));assertFalse(f.consumed[0]);assertFalse(f.requestChase);}
 @Test void generatedSealsDoNotTriggerPhysicalSealCharge(){var r=run("PRE_OPENING",p("A",7000065,List.of(140),Map.of()));assertEquals(1,end(r,1).statuses().get("burningSeal"));assertFalse(r.events().stream().filter(e->e.turn()==1).flatMap(e->e.changes().stream()).anyMatch(c->c.attribute().equals("burningSeal")));}
 @Test void sealNameMatchesContainsRatherThanSuffix(){var r=run("PRE_OPENING",p("A",7000094,List.of(140),Map.of()));assertEquals(0,end(r,1).statuses().get("burningSeal"));assertEquals(1,end(r,1).statuses().get("chaseCount"));}
 @Test void bindingBlocksChaseButDoesNotRefundSealChargeOrSlot(){var r=run("POST_OPENING",p("A",7000001,List.of(),Map.of("binding",1,"burningSeal",1)));assertEquals(List.of(0),end(r,1).consumedSlots());assertEquals(0,end(r,1).statuses().get("burningSeal"));assertTrue(r.events().stream().anyMatch(e->e.turn()==1&&e.type().equals("CHASE_BLOCKED")));}
 @Test void chaseLimitDoesNotRefundSealConsumedOnSecondCard(){var a=p("A",1000005,List.of(),Map.of("agility",10,"burningSeal",1));var cards=new ArrayList<>(a.cards());cards.set(1,7000001);a=new Player(a.id(),a.name(),0,a.hp(),a.maxHp(),a.anima(),0,0,cards,a.talentIds(),a.buffs());var r=run("POST_OPENING",a);assertEquals(List.of(1),end(r,1).consumedSlots());assertEquals(0,end(r,1).statuses().get("burningSeal"));assertEquals(1,end(r,1).statuses().get("chaseCount"));assertTrue(r.events().stream().anyMatch(e->e.turn()==1&&e.type().equals("CHASE_LIMIT")));}
 @Test void sealEventExplicitlyShowsConsumedSlotBeforeBody(){var r=run("PRE_OPENING",p("A",7000001,List.of(140),Map.of()));var e=r.events().stream().filter(x->x.type().equals("TALENT_SEAL")).findFirst().orElseThrow();assertEquals(List.of(0),e.states().getFirst().consumedSlots());assertEquals(0,e.states().getFirst().statuses().get("metalActivation"));}
 @Test void compactAndDetailedRevivalSealPathsAgree(){var a=new Player("A","A",0,1,100,10,0,0,Collections.nCopies(8,7000001),List.of(),Map.of("flameRevive",1,"burningSeal",1,"internalInjury",2));var req=new Request(Rules.ID,"STANDARD","POST_OPENING","A",List.of(a,p("B",1000005,List.of(),Map.of())));var full=engine.simulate(req);var compact=engine.simulateForValidation(req);assertEquals(full.finalStates(),compact.finalStates());assertEquals(full.winnerId(),compact.winnerId());}
 @Test void pairRechecksFirstFighterKilledBySecondFightersRevivalHealing(){var fs=pair(Map.of("flameRevive",1));fs[0].hp=1;fs[1].hp=-1;fs[1].statuses.put("reviveWheel",1);fs[1].statuses.put("reverseRounds",1);assertFalse(deaths(fs[0],fs[1]));assertEquals(15,fs[0].hp);assertEquals(64,fs[1].hp);assertEquals(0,fs[0].status("flameRevive"));}
 @Test void pairRechecksFirstFightersDeathBattleAfterReflectedRevivalHealing(){var fs=pair(Map.of("deathBattleWill",1));fs[0].hp=1;fs[1].hp=-1;fs[1].statuses.put("reviveWheel",1);fs[1].statuses.put("reverseRounds",1);assertFalse(deaths(fs[0],fs[1]));assertTrue(fs[0].hp<=0);assertEquals(1,fs[0].status("deathBattleActive"));}
 @Test void allBlockedWheelAttemptsAreSpentAtOnePairCheck(){var fs=pair(Map.of("reviveWheel",2,"noHealing",1));fs[0].hp=-1;assertTrue(deaths(fs[0],fs[1]));assertEquals(0,fs[0].status("reviveWheel"));assertEquals(2,fs[0].resolution.log.stream().filter(e->e.type().equals("RESURRECTION")).count());}
}
